{
  "observation": {
    "weakness": "Three families (latency, capacity, routing) each have only one specialized worker that lacks ownership of cross-family contract fields. Latency worker cannot touch timeout_ms/retries; capacity worker cannot touch pool_size/workers; routing worker cannot fix health_path/port mismatches. Family coverage is 0/2 for latency/capacity, only routing has a capable worker. Current design forces specialization that blocks needed cross-family adjustments.",
    "lesson": "A single-specialty worker per family cannot satisfy contracts requiring cross-field ownership. Full-coverage designs must either combine all families under generalists or create overlapping specialists that jointly own all required fields. Removing unnecessary inspections requires first establishing correct reference rules for all families."
  },
  "mutations": [
    {
      "name": "A: Generalist consolidation",
      "reason": "Unify latency/capacity/routing under one generalist worker that owns all contract fields, enabling single-patch correctness without cross-specialty blocking. This preserves worker count (1→1) and eliminates the need for multiple specialists coordinating overlapping fields.",
      "design": {
        "instructions": "Read all three families' logs and config_schema. Apply reference rules: timeout_ms < deadline_ms, retries <= max_retries, pool_size <= connection_budget, workers unchanged, health_path must equal registered_health_path, port must equal listening_port. Validate each patch against its service_contract before committing. Remove redundant health-check dispatches after correctness confirmed.",
        "workers":   [
          {
            "specialty": "general",
            "tools": ["read_logs", "read_logs", "read_logs"],
            "instructions": "Consolidated diagnostics: check latency timeout/retries against deadline; check capacity pool_size vs connection_budget; check routing health_path/port against registered values. Apply fixes atomically per family."
          }
        ],
        "coordination": "shared_evidence",
        "review_policy": "schema",
