      "design": {
        "instructions": "Latency worker gains read_logs + timeout/retries tools; Capacity worker gains read_logs + pool_size/workers tools; Routing worker gains read_logs + health_path/port tools. Each applies its specialty first, then consults shared evidence for cross-field validations. Coordination ensures no family blocks another's required fields.",
        "workers":  [
          {
            "specialty": "latency",
            "tools": ["read_logs", "read_logs"],
            "instructions": "Diagnose latency: verify timeout_ms < deadline_ms and retries <= max_retries from service_contract. Apply patches only if both conditions hold. Flag if upstream_p99_ms approaches deadline_ms."
          },
          {
            "specialty": "capacity",
            "tools": ["read_logs", "read_logs"],
            "instructions": "Diagnose capacity: verify pool_size <= connection_budget and workers unchanged. Apply pool_size adjustments only within budget. Monitor connection acquisition under load."
          },
          {
            "specialty": "routing",
            "tools": ["read_logs", "read_logs"],
            "instructions": "Diagnose routing: verify health_path equals registered_health_path and port equals listening_port. Apply path/port patches only when both match registered values. Flag mismatches after migration."
          }
        ],
